jmp_buf env;
volatile int jump_status = 0;

void escape_function() {
    // Return value passed to setjmp (must be non-zero)
    longjmp(env, 101);
}

void execution_flow() {
    jump_status = setjmp(env);

    if (jump_status == 0) {
        // Initial call: Context saved
        // (Execution continues forward)
        escape_function();
    } else {
        // Non-local jump return: Context restored
        // jump_status == 101
    }
}
